import { getAllSyncedAvailableModels } from "./db/models";
import { getResolvedModelCapabilities } from "./modelCapabilities";
import {
  getModelContextOverrideRecord,
  setModelContextOverride,
  removeModelContextOverride,
} from "./db/modelContextOverrides";

/**
 * Feature 5004 — self-correcting context-window reconciler.
 *
 * Compares each model's provider-declared window (captured by `/models` discovery in
 * `syncedAvailableModels`) against the override-free catalog and, when they diverge,
 * pins the discovered value as an `auto:discovery` override so the real window wins in
 * `getModelContextLimit`. It never touches `manual` overrides, and it self-heals by
 * removing a now-redundant auto override when the catalog has caught up.
 *
 * No new network fetch: it reconciles data the managed-model import already persisted,
 * so it does not duplicate `modelsDevSync` / `modelDiscovery`.
 */

export interface DiscoveredWindow {
  provider: string;
  modelId: string;
  window: number | null;
}

export interface ReconcileDeps {
  getCatalogWindow: (provider: string, modelId: string) => number | null;
  getExistingSource: (provider: string, modelId: string) => string | null;
  writeAuto: (provider: string, modelId: string, window: number) => void;
  removeOverride: (provider: string, modelId: string) => void;
}

export interface ReconcileResult {
  scanned: number;
  written: number;
  removed: number;
  skippedManual: number;
}

/**
 * Pure reconcile: given the discovered windows and a set of injectable deps, decide
 * which auto overrides to write/remove. Deterministic and side-effect-free except
 * through the injected `writeAuto`/`removeOverride`.
 */
export function reconcileContextWindows(
  discovered: DiscoveredWindow[],
  deps: ReconcileDeps
): ReconcileResult {
  const result: ReconcileResult = { scanned: 0, written: 0, removed: 0, skippedManual: 0 };
  for (const { provider, modelId, window } of discovered) {
    result.scanned++;
    if (!provider || !modelId) continue;
    if (typeof window !== "number" || !Number.isInteger(window) || window <= 0) continue;

    const existingSource = deps.getExistingSource(provider, modelId);
    if (existingSource === "manual") {
      result.skippedManual++;
      continue;
    }

    const catalog = deps.getCatalogWindow(provider, modelId);
    if (window !== catalog) {
      deps.writeAuto(provider, modelId, window);
      result.written++;
    } else if (existingSource) {
      // Discovered window now matches the catalog and a stale auto override exists → drop it.
      deps.removeOverride(provider, modelId);
      result.removed++;
    }
  }
  return result;
}

/** Flatten the per-provider discovery map into the reconcile input. */
function toDiscoveredWindows(
  byProvider: Record<
    string,
    Array<{ id: string; contextWindow?: number; inputTokenLimit?: number }>
  >
): DiscoveredWindow[] {
  const out: DiscoveredWindow[] = [];
  for (const [provider, models] of Object.entries(byProvider)) {
    for (const m of models) {
      out.push({
        provider,
        modelId: m.id,
        window: m.contextWindow ?? m.inputTokenLimit ?? null,
      });
    }
  }
  return out;
}

/** Run the reconcile against the live DB (discovery → overrides). */
export async function runContextWindowReconcile(): Promise<ReconcileResult> {
  const byProvider = await getAllSyncedAvailableModels();
  const discovered = toDiscoveredWindows(byProvider);
  return reconcileContextWindows(discovered, {
    // Compare against the override-free catalog view. A persisted override must
    // never feed back into the comparison that (re)writes it, or the reconciler
    // oscillates (write → equal → remove → differ → write ...).
    getCatalogWindow: (provider, modelId) =>
      getResolvedModelCapabilities({ provider, model: modelId }, { persistedOverrides: false })
        .contextWindow,
    getExistingSource: (provider, modelId) =>
      getModelContextOverrideRecord(provider, modelId)?.source ?? null,
    writeAuto: (provider, modelId, window) => {
      setModelContextOverride(provider, modelId, window, "auto:discovery");
    },
    removeOverride: (provider, modelId) => {
      removeModelContextOverride(provider, modelId);
    },
  });
}

// --- Periodic job (mirrors modelsDevSync.startPeriodicSync) ---

const DEFAULT_INTERVAL_MS = 24 * 60 * 60 * 1000; // 24h
let reconcileTimer: ReturnType<typeof setInterval> | null = null;

function resolveIntervalMs(): number {
  const raw = process.env.CONTEXT_WINDOW_RECONCILE_INTERVAL;
  if (raw === undefined) return DEFAULT_INTERVAL_MS;
  const seconds = Number(raw);
  if (!Number.isFinite(seconds) || seconds <= 0) return 0; // 0/invalid → disabled
  return Math.floor(seconds * 1000);
}

/**
 * Start the periodic reconcile. Idempotent. Disabled when
 * `CONTEXT_WINDOW_RECONCILE_INTERVAL=0`. Best-effort: failures are swallowed (the
 * static catalog remains the source of truth).
 */
export function startContextWindowReconcile(intervalMs?: number): void {
  if (reconcileTimer) return;
  const interval = intervalMs ?? resolveIntervalMs();
  if (!interval || interval <= 0) return;

  const tick = () => {
    void runContextWindowReconcile().catch(() => {
      // Swallow — reconcile is advisory; the catalog still resolves windows.
    });
  };

  // Initial non-blocking pass, then on the interval.
  setTimeout(tick, 0);
  reconcileTimer = setInterval(tick, interval);
  reconcileTimer.unref?.();
}

export function stopContextWindowReconcile(): void {
  if (reconcileTimer) {
    clearInterval(reconcileTimer);
    reconcileTimer = null;
  }
}

// Adaptive context-budget "dial" (#7005) DB normalizer, extracted out of compression.ts to keep
// that file under the file-size cap. The compute engine (computeTarget.ts / ladder.ts /
// resolveAdaptivePlan.ts) shipped in PR #4716 but this normalizer never existed, so the
// `contextBudget` setting could never be persisted. Mirrors normalizeUltraConfig/
// normalizeAggressiveConfig in compression.ts.
import {
  DEFAULT_CONTEXT_BUDGET,
  type ContextBudgetConfig,
  type ContextBudgetMode,
  type ContextBudgetPolicy,
  type LadderStage,
} from "@omniroute/open-sse/services/compression/adaptiveCompression/types.ts";

type JsonRecord = Record<string, unknown>;

function toRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" ? (value as JsonRecord) : {};
}

function boundedInt(value: unknown, fallback: number, min: number, max: number): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
  return Math.min(max, Math.max(min, Math.floor(value)));
}

function boundedNumber(value: unknown, fallback: number, min: number, max: number): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
  return Math.min(max, Math.max(min, value));
}

const CONTEXT_BUDGET_MODES = new Set<ContextBudgetMode>(["floor", "replace-autotrigger", "off"]);
const CONTEXT_BUDGET_POLICIES = new Set<ContextBudgetPolicy>([
  "reserve-output",
  "percentage",
  "absolute",
]);

function normalizeLadderOverride(value: unknown): LadderStage[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const out: LadderStage[] = [];
  for (const raw of value) {
    const record = toRecord(raw);
    if (typeof record.engine !== "string" || !record.engine.trim()) continue;
    out.push({
      engine: record.engine,
      ...(typeof record.intensity === "string" ? { intensity: record.intensity } : {}),
    });
  }
  return out.length > 0 ? out : undefined;
}

export function normalizeContextBudgetConfig(value: unknown): ContextBudgetConfig {
  const record = toRecord(value);
  const ladderOverride = normalizeLadderOverride(record.ladderOverride);
  return {
    ...DEFAULT_CONTEXT_BUDGET,
    mode:
      typeof record.mode === "string" && CONTEXT_BUDGET_MODES.has(record.mode as ContextBudgetMode)
        ? (record.mode as ContextBudgetMode)
        : DEFAULT_CONTEXT_BUDGET.mode,
    policy:
      typeof record.policy === "string" &&
      CONTEXT_BUDGET_POLICIES.has(record.policy as ContextBudgetPolicy)
        ? (record.policy as ContextBudgetPolicy)
        : DEFAULT_CONTEXT_BUDGET.policy,
    outputReserve: boundedInt(
      record.outputReserve,
      DEFAULT_CONTEXT_BUDGET.outputReserve,
      0,
      Number.MAX_SAFE_INTEGER
    ),
    safetyMargin: boundedInt(
      record.safetyMargin,
      DEFAULT_CONTEXT_BUDGET.safetyMargin,
      0,
      Number.MAX_SAFE_INTEGER
    ),
    pct: boundedNumber(record.pct, DEFAULT_CONTEXT_BUDGET.pct, 0, 1),
    absoluteBudget: boundedInt(
      record.absoluteBudget,
      DEFAULT_CONTEXT_BUDGET.absoluteBudget,
      0,
      Number.MAX_SAFE_INTEGER
    ),
    ...(ladderOverride ? { ladderOverride } : {}),
  };
}

import type { LocalCommandCall } from '../../types/command.js'
import {
  setSessionContextWindowOverride,
  getSessionContextWindowOverride,
  getSessionContextWindowOverrides,
} from '../../utils/context.js'

const HELP = `Usage: /set-context-window [model] <tokens>

Set a session-scoped context window override. Defaults to the active model.

Examples:
  /set-context-window 256000
  /set-context-window gpt-4o 200000
  /set-context-window status

The override takes precedence over discovery, catalog, and provider defaults
for this session only. Use /clear-context-window to remove it.

For a permanent override (survives restart), use modelLimits in settings.json
for custom/discovered models, for example:
  { "modelLimits": { "my-model": { "contextWindow": 1000000 } } }
For a catalogued model, use an exact CLAUDE_CODE_OPENAI_CONTEXT_WINDOWS entry;
catalog values take precedence over modelLimits and prefix env entries.
See docs/advanced-setup.md (Per-model limit overrides).`

export const call: LocalCommandCall = async (args, context) => {
  const trimmed = args.trim()

  if (!trimmed || trimmed === 'help' || trimmed === '-h' || trimmed === '--help') {
    return { type: 'text', value: HELP }
  }

  if (trimmed === 'status' || trimmed === 'current') {
    const overrides = getSessionContextWindowOverrides()
    if (overrides.size === 0) {
      return { type: 'text', value: 'No context window overrides set for this session.' }
    }
    const lines = Array.from(overrides.entries())
      .map(([model, tokens]) => `  ${model}: ${tokens.toLocaleString()} tokens`)
      .join('\n')
    return { type: 'text', value: `Active context window overrides:\n${lines}` }
  }

  const parts = trimmed.split(/\s+/)

  let model: string
  let tokensStr: string

  if (parts.length === 1) {
    model = context.options.mainLoopModel
    tokensStr = parts[0]
  } else if (parts.length === 2) {
    model = parts[0]
    tokensStr = parts[1]
  } else {
    return { type: 'text', value: `Error: expected 1 or 2 arguments, got ${parts.length}.\n\n${HELP}` }
  }

  if (!/^\d+$/.test(tokensStr)) {
    return { type: 'text', value: `Error: "${tokensStr}" is not a valid integer.` }
  }
  const tokens = Number(tokensStr)

  const previous = getSessionContextWindowOverride(model)

  const result = setSessionContextWindowOverride(model, tokens)
  if (!result.ok) {
    return { type: 'text', value: `Error: ${result.error}` }
  }

  const prevDisplay = previous !== undefined
    ? `${previous.toLocaleString()} tokens`
    : 'none (using default)'
  return {
    type: 'text',
    value: `Context window for "${result.normalizedModel}" set to ${tokens.toLocaleString()} tokens (session only).\nPrevious: ${prevDisplay}`,
  }
}

